-- Chamber bands
CREATE TABLE "chamber_bands" (
  "materialid" TEXT NOT NULL PRIMARY KEY REFERENCES "materials" ("materialid"),
  "kind" TEXT NOT NULL CHECK ("kind" IN ('band', 'no-band')),
  "low_c" REAL,
  "low_c_state" TEXT CHECK ("low_c_state" IN ('Not applicable')),
  "high_c" REAL,
  "high_c_state" TEXT CHECK ("high_c_state" IN ('Not applicable')),
  "basis" TEXT NOT NULL,
  "caution" TEXT NOT NULL,
  "source" TEXT NOT NULL,
  CHECK (("low_c" IS NULL) = ("low_c_state" IS NOT NULL)),
  CHECK (("high_c" IS NULL) = ("high_c_state" IS NOT NULL))
) STRICT;

-- Chamber need
CREATE TABLE "chamber_need" (
  "ruleid" TEXT NOT NULL PRIMARY KEY CHECK (("ruleid" GLOB 'CN[0-9][0-9]')),
  "applies_to" TEXT NOT NULL UNIQUE,
  "verdict" TEXT NOT NULL CHECK ("verdict" IN ('within', 'unknown')),
  "status" TEXT NOT NULL CHECK ("status" IN ('reported', 'deciding', 'retired')),
  "reviewed_by" TEXT NOT NULL,
  "reason" TEXT NOT NULL
) STRICT;

-- Class limits
CREATE TABLE "class_limits" (
